@Service
public class OrderService {

    @Autowired
    private EntityManager entityManager;

    @Transactional
    public void processOrderLifecycle(Long orderId) {
        // 1. Transient
        Order newOrder = new Order();
        newOrder.setStatus("PENDING");

        // Transition to Managed
        entityManager.persist(newOrder);
        // newOrder is now managed; changes will be flushed automatically
        newOrder.setTotalAmount(BigDecimal.valueOf(150.00));

        // 2. Detached (Simulated by clearing context)
        Order existingOrder = entityManager.find(Order.class, orderId);
        entityManager.clear(); // existingOrder is now detached
        existingOrder.setStatus("PROCESSING"); // Untracked change

        // Re-attach via merge (returns a NEW managed instance)
        Order managedOrder = entityManager.merge(existingOrder);

        // 3. Removed
        entityManager.remove(managedOrder); // Scheduled for SQL DELETE
    }
}
